#!/usr/bin/env python3
"""Approved root helper: pinned source, backup, isolated restart, rollback."""
import base64
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import subprocess
import sys
import tempfile
import time

TARGET=Path('/opt/central-mcp-approver/approver.py')
BACKUP=Path('/opt/central-mcp-approver/backups/pre_v06_20261002')
SELF=Path('/opt/central-mcp-gateway/upgrade_approver_v06_20261002.py')
RECEIPT=Path('/opt/central-mcp-gateway/approver_v06_receipt.json')
SERVICE='central-mcp-approver.service'
ORIGINAL_SHA='4b4b44fcbf61dc04ffbcc2e205269713cea11a192a531b72dab473eabc5b2026'
CANDIDATE_SHA='85bcdce1a05ae06bde9c9a85c3bd4e938ed47ff26f3db4f30f932d83f2db60dc'
PAYLOAD=''

def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def atomic(p,data,mode):
    if p.is_symlink():raise RuntimeError('symlink rejected')
    fd,tmp=tempfile.mkstemp(prefix='.mcp-approver-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f:
            os.fchown(f.fileno(),0,0);os.fchmod(f.fileno(),mode)
            f.write(data);f.flush();os.fsync(f.fileno())
        os.replace(tmp,p)
        dfd=os.open(str(p.parent),os.O_RDONLY|os.O_DIRECTORY)
        try:os.fsync(dfd)
        finally:os.close(dfd)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def record(status,**details):
    atomic(RECEIPT,json.dumps(dict(status=status,time=time.time(),candidate_sha256=CANDIDATE_SHA,**details),indent=2).encode(),0o644)
def command(args):return subprocess.run(args,capture_output=True,text=True,timeout=40)
def restart_and_check(marker):
    since=str(int(time.time())-1)
    if command(['systemctl','restart',SERVICE]).returncode:raise RuntimeError('service restart failed')
    for _ in range(20):
        time.sleep(1)
        active=command(['systemctl','is-active',SERVICE])
        logs=command(['journalctl','-u',SERVICE,'--since','@'+since,'--no-pager','-o','cat'])
        if active.returncode==0 and marker in logs.stdout:
            time.sleep(2)
            if command(['systemctl','is-active',SERVICE]).returncode==0:return
    raise RuntimeError('service readiness was not confirmed')
def restore():
    old=(BACKUP/'approver.py').read_bytes()
    if hashlib.sha256(old).hexdigest()!=ORIGINAL_SHA:raise RuntimeError('backup hash mismatch')
    atomic(TARGET,old,0o500)
    restart_and_check('approver avviato')

def main(action):
    if os.geteuid()!=0 or SELF.resolve()!=Path(__file__).resolve():raise RuntimeError('installed root helper required')
    st=SELF.lstat()
    if not stat.S_ISREG(st.st_mode) or st.st_uid!=0 or st.st_mode&0o022:raise RuntimeError('unsafe helper')
    if TARGET.is_symlink() or TARGET.stat().st_uid!=0:raise RuntimeError('unsafe target')
    fd=os.open('/run/lock/mcp-andrea-approver-maintenance.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
    try:
        if action=='--apply':
            if digest(TARGET)!=ORIGINAL_SHA:raise RuntimeError('source changed; review required')
            data=base64.b64decode(PAYLOAD,validate=True)
            if hashlib.sha256(data).hexdigest()!=CANDIDATE_SHA:raise RuntimeError('candidate hash mismatch')
            compile(data,str(TARGET),'exec')
            BACKUP.mkdir(parents=True,mode=0o700,exist_ok=False)
            atomic(BACKUP/'approver.py',TARGET.read_bytes(),0o500)
            atomic(TARGET,data,0o500)
            # The independent transient service survives the approver's restart.
            result=command(['systemd-run','--unit=central-mcp-approver-upgrade-v06-20261002',
                            '--on-active=10s','--collect','/usr/bin/python3',str(SELF),'--activate'])
            if result.returncode:
                atomic(TARGET,(BACKUP/'approver.py').read_bytes(),0o500)
                raise RuntimeError('restart scheduling failed; original source restored')
            record('restart_scheduled',backup=str(BACKUP))
            print(json.dumps({'status':'restart_scheduled','receipt':str(RECEIPT),'backup':str(BACKUP)}))
        elif action=='--activate':
            if digest(TARGET)!=CANDIDATE_SHA:raise RuntimeError('candidate changed before activation')
            try:
                restart_and_check('approver avviato v0.6')
                record('active',backup=str(BACKUP))
            except Exception:
                try:restore();record('rolled_back',reason='new service readiness failed')
                except Exception:record('rollback_failed');raise
        elif action=='--rollback':
            if digest(TARGET)!=CANDIDATE_SHA:raise RuntimeError('rollback conflict')
            # Do not restart inside an approval subprocess; use an isolated job.
            result=command(['systemd-run','--unit=central-mcp-approver-rollback-v06-20261002',
                            '--on-active=10s','--collect','/usr/bin/python3',str(SELF),'--restore'])
            if result.returncode:raise RuntimeError('rollback scheduling failed')
            print('rollback_scheduled')
        elif action=='--restore':
            if digest(TARGET)!=CANDIDATE_SHA:raise RuntimeError('rollback conflict')
            restore();record('rolled_back',reason='approved rollback')
        else:raise ValueError('invalid action')
    finally:os.close(fd)

if __name__=='__main__':
    if len(sys.argv)!=2:raise SystemExit('exactly one action required')
    main(sys.argv[1])
